fn find_min(a: &[i32], lo: usize) -> usize {
    // We assume a.len() > 0 and lo < a.len().
    let mut min_idx = lo;
    let mut i = lo + 1;
    while i < a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
        i += 1;
    }
    min_idx
}

